      "oracle_outputs": {
        "phi_over_phi_c": {
          "op": "subtract",
          "args": [
            {"var": "one"},
            {"op": "multiply",
             "args": [
               {"param": "a_phi_ref"},
               {"op": "power",
                "args": [
                  {"op": "add",
                   "args": [
                     {"var": "J"},
                     {"op": "multiply",
                      "args": [
                        {"param": "alpha_phi_ref"},
                        {"op": "power", "args": [{"var": "I"}, {"param": "two"}]}
                      ]}
                   ]},
                  {"param": "half"}
                ]}
             ]}
