          "domain_statement": "I ranges over the viscous-inertial transition; the paper reports St range 0.01-300, and I is related to St and J. The exact I range is not explicitly given, but the transition occurs at St=10.",
          "anchors": [
            {"line_start": 115, "line_end": 115, "support": "I^2 = rho_p d^2 dot_gamma^2 / P"},
            {"line_start": 238, "line_end": 238, "support": "Range of St numbers in this study is 0.01-300"}
          ]
        }
      ],
      "readout_names": ["phi_over_phi_c"],
      "fixed_condition_ids": ["ref_friction", "restitution_coeff", "shear_cell_geometry", "pressure_imposed"],
      "applicability": "Valid for mu_f=0.15, in the viscous-inertial transition regime, with St range 0.01-300. The fit is reported for the reference friction case.",
      "statistical_basis": "Data collapse across three viscosities (eta_f=10,100,1000) at varying shear rates; phi_c and a_phi obtained by fitting 1-phi/phi_c with K^{1/2}.",
      "uncertainty": "phi_c has uncertainty ±0.02 (source_unspecified); no uncertainty reported for a_phi or alpha_phi.",
      "depends_on": [],
      "anchors": [
        {"line_start": 246, "line_end": 250, "support": "K_phi defined with alpha_phi=0.1; phi data collapse, indicating transition at St_{v->i}=10"},
        {"line_start": 177, "line_end": 177, "support": "Fit phi = phi_c(1 - a_phi K_phi^{1/2}) with a_phi=0.62"},
        {"line_start": 358, "line_end": 358, "support": "Table values for mu_f=0.15"}
      ]
    },
    {
      "claim_id": "mu_scaling",
      "statement": "The macroscopic friction coefficient mu follows mu = mu_c (1 + a_mu K_mu^{1/2}) with K_mu = J + alpha_mu I^2, alpha_mu = 0.029, a_mu = 14.3, mu_c = 0.30, for mu_f = 0.15. This gives a transitional Stokes number St_{v->i}^{mu}=35.",
      "quantitative_form": "mu/mu_c = 1 + a_mu * (J + alpha_mu * I^2)^{1/2}",
      "oracle_outputs": {
